%\usepackage[backend=bibtex]{biblatex}
%\addbibresource{main_bibliography.bib}

\begin{document}

References for Chapter 1:
\bibliographystyle{chapter_1_style}
\bibliography{chapter_1_bibliography}

References for Chapter 2:
